class Solution:
    def maxProfit(self, n: int, edges: List[List[int]], score: List[int]) -> int:
        pre = [0] * n
        for u, v in edges:
            pre[v] |= 1 << u
        dp = [-1] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            if dp[mask] < 0:
                continue
            pos = bin(mask).count('1') + 1
            for i in range(n):
                if not (mask >> i) & 1 and pre[i] & mask == pre[i]:
                    nm = mask | (1 << i)
                    val = dp[mask] + score[i] * pos
                    if val > dp[nm]:
                        dp[nm] = val
        return dp[-1]

