class Solution {
public:
    int maxProfit(int n, vector<vector<int>>& edges, vector<int>& score) {
        vector<int> pre(n, 0);
        for (auto& e : edges) pre[e[1]] |= 1 << e[0];
        vector<long long> dp(1 << n, -1);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] < 0) continue;
            int pos = __builtin_popcount(mask) + 1;
            for (int i = 0; i < n; i++) {
                if (!(mask >> i & 1) && (pre[i] & mask) == pre[i]) {
                    int nm = mask | (1 << i);
                    dp[nm] = max(dp[nm], dp[mask] + (long long)score[i] * pos);
                }
            }
        }
        return (int)dp[(1 << n) - 1];
    }
};

