class Solution {
    public int maxProfit(int n, int[][] edges, int[] score) {
        int[] pre = new int[n];
        for (int[] e : edges) pre[e[1]] |= 1 << e[0];
        long[] dp = new long[1 << n];
        java.util.Arrays.fill(dp, -1);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] < 0) continue;
            int pos = Integer.bitCount(mask) + 1;
            for (int i = 0; i < n; i++) {
                if ((mask >> i & 1) == 0 && (pre[i] & mask) == pre[i]) {
                    int nm = mask | (1 << i);
                    dp[nm] = Math.max(dp[nm], dp[mask] + (long) score[i] * pos);
                }
            }
        }
        return (int) dp[(1 << n) - 1];
    }
}

